-- Den Designer: the mesh catalog (catalog_data.lua, generated by tools/build_catalog.py). Pure Lua: shelves,
-- search and labels; the editor turns them into list items. Loaded the first time the catalog opens.
local M = {}

M.STRIDE = 6        -- path, width, depth, height, shelf, has collision
M.SEARCH_LIMIT = 300
M.RECENT_LIMIT = 40

-- "SM_UNI_CrateR8A_Small" -> "CrateR8A Small"
function M.name_of(path)
    local name = type(path) == "string" and path:match("([^/%.]+)$") or "?"
    name = name:gsub("^SM_", ""):gsub("^(%u%u%u)_", "%1 "):gsub("^UNI ", ""):gsub("^HUB ", ""):gsub("_", " ")
    return name
end

function M.new(data)
    data = data or require("catalog_data")
    local self = { shelves = {}, recent = {} }
    local items, stride = data.items, M.STRIDE
    local count = #items / stride
    local lower, by_path = {}, {}
    local first = {}
    for i = 1, count do
        local base = (i - 1) * stride
        local path = items[base + 1]
        lower[i] = M.name_of(path):lower() .. " " .. path:lower()
        by_path[path] = i
        local shelf = items[base + 5]
        if not first[shelf] then first[shelf] = i end
    end
    for index, c in ipairs(data.categories) do
        self.shelves[index] = { key = tostring(index), title = c[1], count = c[2], first = first[index] or 1 }
    end
    self.count = count

    -- One item: { index, path, name, size = { w, d, h }, shelf, solid }.
    function self:item(i)
        local base = (i - 1) * stride
        if not items[base + 1] then return nil end
        return { index = i, path = items[base + 1], name = M.name_of(items[base + 1]),
                 size = { items[base + 2], items[base + 3], items[base + 4] },
                 shelf = items[base + 5], solid = items[base + 6] == 1 }
    end

    function self:find(path) return by_path[path] end

    -- Item indices on a shelf (a category index, or "recent").
    function self:shelf_items(key)
        if key == "recent" then
            local out = {}
            for _, path in ipairs(self.recent) do
                local i = by_path[path]
                if i then out[#out + 1] = i end
            end
            return out
        end
        local shelf = self.shelves[tonumber(key) or 0]
        if not shelf then return {} end
        local out = {}
        for i = shelf.first, shelf.first + shelf.count - 1 do out[#out + 1] = i end
        return out
    end

    -- Every word must appear in the name or path; at most SEARCH_LIMIT results, plus the total.
    function self:search(text)
        local words = {}
        for w in tostring(text or ""):lower():gmatch("%S+") do words[#words + 1] = w end
        if #words == 0 then return {}, 0 end
        local out, total = {}, 0
        for i = 1, count do
            local hay, ok = lower[i], true
            for _, w in ipairs(words) do
                if not hay:find(w, 1, true) then ok = false; break end
            end
            if ok then
                total = total + 1
                if #out < M.SEARCH_LIMIT then out[#out + 1] = i end
            end
        end
        return out, total
    end

    function self:remember(path)
        for i = #self.recent, 1, -1 do if self.recent[i] == path then table.remove(self.recent, i) end end
        table.insert(self.recent, 1, path)
        while #self.recent > M.RECENT_LIMIT do table.remove(self.recent) end
    end

    return self
end

-- "72 x 71 x 40 cm"; meshes over 2 m in metres.
function M.size_text(size)
    local big = math.max(size[1], size[2], size[3]) >= 200
    if big then return string.format("%.1f x %.1f x %.1f m", size[1] / 100, size[2] / 100, size[3] / 100) end
    return string.format("%d x %d x %d cm", size[1], size[2], size[3])
end

return M
